#pragma once

#include <cstdint>
#include <span>
#include <string_view>

namespace fo4::hkx {

struct HkxRelayoutOffset {
  std::uint32_t wide;
  std::uint32_t narrow;
};

// Invariant: offsets list the stored members of the decode-table class in its member order, as (8-byte, 4-byte) offsets; generated by tools/hkx_relayout_codegen.py.
struct HkxRelayoutClass {
  std::string_view name;
  std::uint32_t wide_size;
  std::uint32_t narrow_size;
  std::span<const HkxRelayoutOffset> offsets;
};

std::span<const HkxRelayoutClass> relayout_classes();

}  // namespace fo4::hkx
